// nolint
func newBackupCmd() *cobra.Command {
	backupNodeCmd := &cobra.Command{
		Use:   "node <node> <target folder> <path to ssh key>",
		Short: "Backup db node",
		Args: func(cmd *cobra.Command, args []string) error {
			if len(args) != 3 {
				return ErrInvalidNumberOfArguments
			}
			return nil
		},
		RunE: backupNode,
	}

	backupCronCmd := &cobra.Command{
		Use:   "cron <cron expression>",
		Short: "Installation of a scheduled database backup",
		Args: func(cmd *cobra.Command, args []string) error {
			if len(args) != 1 {
				return ErrInvalidNumberOfArguments
			}
			return nil
		},
		RunE: backupCron,
	}

	backupCronCmd.PersistentFlags().StringVar(&sshKey, "ssh-key", "", "Path to SSH key")

	backupCmd := &cobra.Command{
		Use:   "backup",
		Short: "Backup database",
	}

	backupCmd.AddCommand(backupNodeCmd, backupCronCmd)

	return backupCmd

}

var ErrInvalidCronExpression = errors.New("invalid cron expression")

func validateBackupCronCmd(cmd *cmdType, cluster *clusterType) error {
	args := cmd.Args

	if len(args) != 2 {
		return ErrInvalidNumberOfArguments
	}

	if !validCronExpression(args[1]) {
		return ErrInvalidCronExpression
	}

	return nil
}

// nolint
func validateBackupNodeCmd(cmd *cmdType, cluster *clusterType) error {
	args := cmd.Args

	if len(args) != 4 {
		return ErrInvalidNumberOfArguments
	}

	var err error

	if n := cluster.nodeByHost(args[1]); n == nil {
		err = errors.Join(err, fmt.Errorf(errHostNotFoundInCluster, args[1], ErrHostNotFoundInCluster))
	}

	if !fileExists(args[3]) {
		err = errors.Join(err, fmt.Errorf(errSshKeyNotFound, args[3], ErrFileNotFound))
	}

	return err
}

func backupNode(cmd *cobra.Command, args []string) error {
	loggerInfo("backup node", args[0])
	cluster := newCluster()

	Cmd := newCmd(ckBackup, append([]string{"node"}, args...))

	if err := Cmd.validate(cluster); err != nil {
		return err
	}

	err := mkCommandDirAndLogFile(cmd, cluster)
	if err != nil {
		return err
	}

	loggerInfoGreen("backupnode.sh", strings.Join(args, " "))
	if err = newScriptExecuter("", "").
		run("backupnode.sh", args...); err != nil {
		return err
	}

	return nil
}

func backupCron(cmd *cobra.Command, args []string) error {
	loggerInfo("backup cron", args[0])

	cluster := newCluster()

	c := newCmd(ckBackup, append([]string{"cron"}, args...))

	if err := c.validate(cluster); err != nil {
		return err
	}

	err := mkCommandDirAndLogFile(cmd, cluster)
	if err != nil {
		return err
	}

	if err = cluster.applyCmd(c); err != nil {
		return err
	}

	if err = cluster.Cmd.apply(cluster); err != nil {
		return err
	}

	return nil
}

// validCronExpression checks that the passed value is a valid standard
// 5-field cron expression: minute hour day-of-month month day-of-week
func validCronExpression(expr string) bool {
	fields := strings.Fields(strings.TrimSpace(expr))
	if len(fields) != 5 {
		return false
	}

	specs := []cronFieldSpec{
		{min: 0, max: 59}, // minute
		{min: 0, max: 23}, // hour
		{min: 1, max: 31}, // day of month
		{min: 1, max: 12, names: map[string]int{
			"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
			"jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12,
		}},
		{min: 0, max: 7, names: map[string]int{
			"sun": 0, "mon": 1, "tue": 2, "wed": 3, "thu": 4, "fri": 5, "sat": 6,
		}},
	}

	for i, field := range fields {
		if !validCronField(field, specs[i]) {
			return false
		}
	}

	return true
}

type cronFieldSpec struct {
	min, max int
	names    map[string]int
}

func validCronField(field string, spec cronFieldSpec) bool {
	for _, item := range strings.Split(field, ",") {
		if !validCronItem(item, spec) {
			return false
		}
	}
	return true
}

func validCronItem(item string, spec cronFieldSpec) bool {
	step := 1
	if idx := strings.Index(item, "/"); idx >= 0 {
		v, err := strconv.Atoi(item[idx+1:])
		if err != nil || v <= 0 {
			return false
		}
		step = v
		item = item[:idx]
	}

	if item == "*" {
		return true
	}

	if idx := strings.Index(item, "-"); idx >= 0 {
		from, ok1 := parseCronValue(item[:idx], spec)
		to, ok2 := parseCronValue(item[idx+1:], spec)
		return ok1 && ok2 && from >= spec.min && to <= spec.max && from <= to
	}

	v, ok := parseCronValue(item, spec)
	return ok && v >= spec.min && v <= spec.max && step > 0
}

func parseCronValue(s string, spec cronFieldSpec) (int, bool) {
	if v, ok := spec.names[strings.ToLower(s)]; ok {
		return v, true
	}
	v, err := strconv.Atoi(s)
	return v, err == nil
}

