func TestValidCronExpression(t *testing.T) {
	require := require.New(t)

	validExprs := []string{
		"0 2 * * *",
		"*/15 0 * * *",
		"0 0 1 1 0",
		"5 4 * * sun",
		"0 12 */5 * mon-fri",
		"*/5 */10 * * *",
		"30 6,18 * * *",
		"0-59 * * * *",
		"45 3-8 * * *",
		"* * * JAN-DEC SUN-SAT",
		"0 0 1-15 * *",
	}

	for _, expr := range validExprs {
		require.True(validCronExpression(expr), "expected valid cron expression: %s", expr)
	}

	invalidExprs := []string{
		"",
		"0 2 * *",
		"not-a-cron",
		"60 * * * *",
		"* 24 * * *",
		"* * 0 * *",
		"* * 32 * *",
		"* * * 13 *",
		"* * * * 8",
		"0 2 * * * *",
		"*/0 * * * *",
	}

	for _, expr := range invalidExprs {
		require.False(validCronExpression(expr), "expected invalid cron expression: %s", expr)
	}
}

